
/* ================= setup sheets (before = today rebuilt, after = Light touch) ================= */
const bSeg = (list, on = 0) => `<div class="inline-flex w-full gap-0.5 rounded-xl border border-[var(--color-brand-border)] bg-[var(--color-brand-elevated)] p-[3px]">${list.map((l, i) => `<span class="${i === on ? SEG_ON : SEG_OFF}">${l}</span>`).join('')}</div>`
const bCard = (html, cls = '') => `<div class="mt-4 rounded-2xl border border-[var(--color-brand-border)] bg-[var(--color-brand-card)] p-3.5 ${cls}">${html}</div>`
const bBuddgy = (t, pill) => `<div class="mt-4 flex gap-3 rounded-2xl bg-[var(--color-brand-primary-soft)] p-3.5"><span class="flex size-8 shrink-0 items-center justify-center rounded-full bg-[var(--color-brand-card)] text-[var(--color-brand-primary-ink)]">${ICON('sparkles', 'size-4')}</span><span class="text-[0.8125rem] leading-snug text-[var(--color-brand-text-primary)]"><b class="font-semibold">Why Buddgy sized it</b> ${pill ? badge('brand', pill) : ''}<br>${t}</span></div>`
const bDanger = (l) => `<button type="button" class="${BTN_CORE} mt-2 h-11 w-full rounded-xl border-[var(--color-brand-red)] text-[var(--color-brand-red)]">${ICON('trash-2', 'size-4')}${l}</button>`
const bRadio = (t, s, on) => `<div class="mb-2 ${on ? CARD_SEL : CARD_UNSEL}"><span class="flex size-5 shrink-0 items-center justify-center rounded-full border-2 ${on ? 'border-[var(--color-brand-primary)]' : 'border-[var(--color-brand-border-strong)]'}">${on ? '<span class="size-2.5 rounded-full bg-[var(--color-brand-primary)]"></span>' : ''}</span><span class="min-w-0 flex-1"><span class="block text-[0.9375rem] font-semibold">${t}</span><span class="block text-xs ${SECOND}">${s}</span></span></div>`

/* after: one form language */
const gRow = (k, v, tap = 'Opens the picker') => `<button type="button" data-toast="${esc(tap)}" class="flex min-h-[52px] w-full items-center gap-3 px-4 text-start hover:bg-[var(--color-brand-elevated)]"><span class="w-[112px] shrink-0 text-[0.84375rem] ${SECOND}">${k}</span><span class="flex min-w-0 flex-1 items-center justify-end gap-2 text-[0.9375rem] font-medium text-[var(--color-brand-text-primary)]">${v}${ICON('chevron-right', `size-4 shrink-0 ${MUTED}`)}</span></button>`
const gStatic = (k, v) => `<div class="flex min-h-[52px] items-center gap-3 px-4"><span class="w-[112px] shrink-0 text-[0.84375rem] ${SECOND}">${k}</span><span class="flex min-w-0 flex-1 items-center justify-end gap-2 font-mono-numbers text-[0.9375rem] font-medium text-[var(--color-brand-text-primary)]">${v}</span></div>`
const gSw = (k, help, on) => `<button type="button" data-sw role="switch" aria-checked="${on}" class="flex min-h-[52px] w-full items-center gap-3 px-4 py-2.5 text-start"><span class="min-w-0 flex-1"><span class="block text-[0.9375rem] font-medium text-[var(--color-brand-text-primary)]">${k}</span>${help ? `<span class="block text-xs ${SECOND}">${help}</span>` : ''}</span><span aria-hidden="true" class="lt-sw relative h-[26px] w-[44px] shrink-0 rounded-full ${on ? 'bg-[var(--color-brand-primary)]' : 'bg-[var(--color-brand-border-strong)]'}"><span class="absolute top-[3px] size-5 rounded-full bg-white shadow-[0_1px_3px_rgba(0,0,0,.25)] transition-all" style="inset-inline-start:${on ? 21 : 3}px"></span></span></button>`
const gIn = (k, ph, val = '') => `<label class="flex min-h-[52px] items-center gap-3 px-4"><span class="w-[112px] shrink-0 text-[0.84375rem] ${SECOND}">${k}</span><input value="${esc(val)}" placeholder="${esc(ph)}" class="min-w-0 flex-1 bg-transparent text-end text-[0.9375rem] text-[var(--color-brand-text-primary)] outline-none placeholder:text-[var(--color-brand-text-muted)]"></label>`
const gStep = (k, val, unit = '') => `<div class="flex min-h-[52px] items-center gap-3 px-4"><span class="min-w-0 flex-1 text-[0.84375rem] ${SECOND}">${k}</span><span class="flex items-center gap-1"><button type="button" data-step="-1" aria-label="Less" class="${CLOSE_BTN}">${ICON('chevron-left', 'size-4')}</button><b data-val class="min-w-[64px] text-center font-mono-numbers text-[0.9375rem] font-semibold text-[var(--color-brand-text-primary)]" data-unit="${unit}">${val}${unit}</b><button type="button" data-step="1" aria-label="More" class="${CLOSE_BTN}">${ICON('chevron-right', 'size-4')}</button></span></div>`
const gSeg = (opts, on = 0) => `<div class="p-1.5"><div class="inline-flex w-full gap-0.5 rounded-xl bg-[var(--color-brand-elevated)] p-[3px]" data-seggroup>${opts.map((o, i) => `<button type="button" data-segopt class="${i === on ? SEG_ON : SEG_OFF}">${o}</button>`).join('')}</div></div>`
const group = (rows, head = '', foot = '') => `${head ? sectionHead(head).replace('pt-1', 'pt-5') : '<div class="h-3"></div>'}<div class="mx-4 divide-y divide-[var(--color-brand-border)] overflow-hidden ${CARDBOX}">${rows.join('')}</div>${foot ? `<p class="mx-5 mt-2 text-xs leading-relaxed ${MUTED}">${foot}</p>` : ''}`
const gNote = (t) => `<div class="mx-4 mt-3 flex gap-3 rounded-2xl bg-[var(--color-brand-primary-soft)] px-4 py-3"><span class="mt-0.5 text-[var(--color-brand-primary-ink)]">${ICON('sparkles', 'size-4')}</span><span class="text-[0.8125rem] leading-snug text-[var(--color-brand-text-primary)]">${t}</span></div>`
const heroAmt = (big, unit, line, tile) => `<div class="flex flex-col items-center px-5 pb-4 pt-2 text-center">${tile ? `<span aria-hidden="true" class="mb-3 flex size-[52px] items-center justify-center rounded-[16px]" style="background:${tile[1]};color:${tile[2]}">${ICON(tile[0], 'size-6')}</span>` : ''}<div class="flex items-baseline justify-center gap-1.5"><span class="font-mono-numbers text-[2.5rem] font-semibold leading-none tracking-[-0.04em] tabular-nums text-[var(--color-brand-text-primary)]">${big}</span>${unit ? `<span class="text-[0.9375rem] font-semibold ${MUTED}">${unit}</span>` : ''}</div>${line ? `<p class="mt-2 text-[0.8125rem] ${SECOND}">${line}</p>` : ''}</div>`
const barLine = (pct, tone = 'var(--color-brand-primary)', ticks = []) => `<div class="relative mx-auto mt-1 h-1.5 w-[calc(100%-2.5rem)] rounded-full bg-[var(--color-brand-sunken)]"><div class="h-full rounded-full" style="width:${pct}%;background:${tone}"></div>${ticks.map((t) => `<span class="absolute -top-1 h-3.5 w-[2px] rounded bg-[var(--color-brand-text-muted)]" style="inset-inline-start:${t}%"></span>`).join('')}</div>`
function ltForm(S, o) {
  const foot = `<div class="flex flex-col gap-1">${o.danger ? `<button type="button" data-done class="${BTN_CORE} h-12 w-full rounded-xl border-transparent bg-[var(--color-brand-red)] text-[0.9375rem] text-[var(--color-brand-on-red)]">${o.cta}</button>` : `<button type="button" data-done class="${BTN.primary} ${SZ.block}">${o.cta}</button>`}${o.link ? `<button type="button" data-done="link" class="h-11 text-[0.875rem] font-semibold ${o.danger ? SECOND : 'text-[var(--color-brand-primary-ink)]'}">${o.link}</button>` : ''}</div>`
  const sh = ltSheet(S, o.title, o.sub || '', o.body, o.cta ? foot : '', o.z || 120, undefined, o.menu ? `<button type="button" data-menu aria-label="More actions" class="${CLOSE_BTN}">${ICON('ellipsis-vertical', 'size-4')}</button>` : '')
  if (o.lead) sh.el.querySelector('h2').parentElement.insertAdjacentHTML('beforebegin', o.lead)
  sh.el.addEventListener('click', (e) => {
    const t = e.target
    const sw = t.closest('[data-sw]')
    if (sw) { const on = sw.getAttribute('aria-checked') !== 'true'; sw.setAttribute('aria-checked', on); const tr = sw.querySelector('.lt-sw'); tr.classList.toggle('bg-[var(--color-brand-primary)]', on); tr.classList.toggle('bg-[var(--color-brand-border-strong)]', !on); tr.firstElementChild.style.insetInlineStart = on ? '21px' : '3px'; o.onSw?.(sw, on, sh); return }
    const sg = t.closest('[data-segopt]')
    if (sg) { sg.parentElement.querySelectorAll('[data-segopt]').forEach((b) => { b.className = b === sg ? SEG_ON : SEG_OFF }); o.onSeg?.(sg, sh); return }
    const st = t.closest('[data-step]')
    if (st) { const v = st.parentElement.querySelector('[data-val]'); const n = Math.max(1, (parseInt(v.textContent, 10) || 0) + +st.dataset.step); v.textContent = `${n}${v.dataset.unit}`; return }
    const rd = t.closest('[data-pick]')
    if (rd) { rd.parentElement.querySelectorAll('[data-pick]').forEach((b) => { const on = b === rd; b.setAttribute('aria-checked', on); const dot = b.querySelector('[data-dot]'); if (dot) dot.outerHTML = tick(on, false).replace('<span', '<span data-dot') }); o.onPick?.(rd, sh); return }
    const ex = t.closest('[data-expand]')
    if (ex) { const n = ex.nextElementSibling; n.hidden = !n.hidden; return }
    if (t.closest('[data-menu]')) return toast(S, o.menu)
    const ts = t.closest('[data-toast]'); if (ts) return toast(S, ts.dataset.toast)
    const dn = t.closest('[data-done]'); if (dn) { sh.close(); toast(S, dn.dataset.done === 'link' ? (o.linkDone || 'Done') : (o.done || 'Saved')) }
  })
  return sh
}
const pickRow = (t, s, on, icon, extra = '') => `<button type="button" data-pick role="radio" aria-checked="${on}" class="flex min-h-[56px] w-full items-center gap-3 px-4 py-2.5 text-start">${icon ? `<span aria-hidden="true" class="flex size-9 shrink-0 items-center justify-center rounded-[11px]" style="background:${icon[1]};color:${icon[2]}">${ICON(icon[0], 'size-[18px]')}</span>` : ''}<span class="min-w-0 flex-1"><span class="flex items-center gap-1.5 text-[0.9375rem] font-semibold text-[var(--color-brand-text-primary)]">${t}${extra}</span>${s ? `<span class="block text-xs ${SECOND}">${s}</span>` : ''}</span>${tick(on, false).replace('<span', '<span data-dot')}</button>`
const TILE = (ic, tone) => `<span aria-hidden="true" class="flex size-10 shrink-0 items-center justify-center rounded-[12px]" style="background:${tone[0]};color:${tone[1]}">${ICON(ic, 'size-5')}</span>`

